window.kbPageData["views/entry/k-deaf678e08e0ae9c"] = {"key":"entry/k-deaf678e08e0ae9c","state":{"route":"entry/k-deaf678e08e0ae9c"},"node":{"id":"k-deaf678e08e0ae9c","mode":"k","title":"规则开放","type":"概念与词义","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["规则开放为制度型开放提供基本行为准则"],"qs":["政治理论必刷100题#39"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"主类":["概念与词义"],"出处性质":["专项题解析"],"学科":["政治理论"],"资料类别":["政治理论专项"]},"directorySummary":"规则开放是制度型开放的一项基础内容，包括遵守现行国际经贸规则，以及通过参与全球治理共建新的国际经贸规则。世界贸易组织规则和区域贸易协定规则是典型对象。","review":{"definition":"规则开放是制度型开放的一项基础内容，包括遵守现行国际经贸规则，以及通过参与全球治理共建新的国际经贸规则。世界贸易组织规则和区域贸易协定规则是典型对象。","explanation":"按杨继军《以制度型开放建设更高水平开放型经济新体制》的划分，规则开放着眼于国际经贸活动共同遵循的准则，规制开放着眼于政府监管规则的协调。A项说规则开放为制度型开放提供基本行为准则，符合原文。选非题的错误在C项，原文概括管理开放的核心时用的是“简政放权”。","references":[{"source":"web-cba87052d87a44ca","location":"“制度型开放的主要内容”之“规则开放”段","quote":"共建国际经贸新规则"}],"evidence":"规则开放是制度型开放的基础，为制度型开放提供基本行为准则。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"政治理论必刷100题#39":{"paper":"政治理论必刷100题","n":39,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",12],"asrc":["国省考政治理论必刷100题.pdf",56],"card":"5437719768ca8ab16463a2c3","links":[{"id":"k-deaf678e08e0ae9c","role":"直接考查","why":"对接并参与建设国际经贸规则是规则开放发挥基础作用的体现。"}]}},"terms":{},"references":{"web-cba87052d87a44ca":{"name":"杨继军《以制度型开放建设更高水平开放型经济新体制》","url":"https://www.qstheory.cn/20250218/d2719a88f1954af19030c16916f2ff6d/c.html"}},"topics":[],"units":{"k-deaf678e08e0ae9c":[["政治理论必刷100题#39"]]}};
